//#region plugins/buddy/index.jsx
const { plugin: { store }, flux: { dispatcher, storesFlat: { UserStore, ChannelStore, RelationshipStore } } } = shelter;
const DEFAULTS = {
	sam: true,
	samVoice: "Adult Male #2, American English (TruVoice)",
	samPitch: 130,
	samSpeed: 150,
	wander: true,
	dodge: true,
	watch: true,
	antics: true,
	hue: 0,
	hat: "",
	blockExtra: "",
	speak: true,
	mentions: true,
	chatter: 15,
	scale: 2,
	voice: "",
	rate: 1,
	pitch: 1,
	volume: 80
};
let lastReact = 0;
function onMessage({ message, optimistic }) {
	if (optimistic || !store.mentions || !message?.author) return;
	const me = UserStore.getCurrentUser();
	if (!me || message.author.id === me.id) return;
	if (!RelationshipStore?.isFriend(message.author.id)) return;
	const channel = ChannelStore.getChannel(message.channelId);
	const dm = channel?.type === 1;
	const mentioned = message.mentions?.some((m) => m.id === me.id);
	if (!dm && !mentioned) return;
	if (Date.now() - lastReact < 15e3) return;
	lastReact = Date.now();
	const name = message.author.global_name ?? message.author.username;
	const target = dm ? document.querySelector(`a[href="/channels/@me/${message.channelId}"]`) : document.querySelector(`[data-list-item-id="guildsnav___${channel?.guild_id}"]`);
	ping(dm ? `${name} sent you a message!` : `${name} mentioned you!`, target);
}
function onLoad() {
	if (!RelationshipStore) console.warn("[buddy] RelationshipStore not found; friend pings are off");
	for (const [k, v] of Object.entries(DEFAULTS)) store[k] ??= v;
	if (store.samRev !== 2) {
		store.samVoice = DEFAULTS.samVoice;
		store.samPitch = DEFAULTS.samPitch;
		store.samSpeed = DEFAULTS.samSpeed;
		store.samRev = 2;
	}
	dispatcher.subscribe("MESSAGE_CREATE", onMessage);
	start();
	startEvents();
	startMenu(pick);
}
function onUnload() {
	dispatcher.unsubscribe("MESSAGE_CREATE", onMessage);
	stopEvents();
	stopMenu();
	stop();
}

//#endregion
exports.onLoad = onLoad
exports.onUnload = onUnload
Object.defineProperty(exports, 'settings', {
  enumerable: true,
  get: function () {
    return Settings;
  }
});
return exports;
